steps.run:
test "$(node --version)" = v24.20.0
test "$(pnpm --version)" = 9.15.4
timeout --kill-after=5s 240s pnpm install --frozen-lockfile --ignore-scripts --store-dir "$RUNNER_TEMP/flow-ci-store"
node --input-type=module - <<'NODE'
import { readFileSync } from 'node:fs';
import assert from 'node:assert/strict';
assert.equal(JSON.parse(readFileSync('node_modules/vitest/package.json', 'utf8')).version, '4.0.18');
assert.equal(process.env.FLOW_TEST_DATABASE_URL, 'postgresql://flow:flow-local-only@127.0.0.1:55432/flow_c01');
NODE
git diff --exit-code -- package.json pnpm-lock.yaml pnpm-workspace.yaml
git rev-parse HEAD

timeout --kill-after=2s 15s node --input-type=module - <<'NODE'
import { readFileSync, statSync, appendFileSync } from 'node:fs';
import { join } from 'node:path';
const read = (name, limit) => {
  const path = join(process.env.RUNNER_TEMP, `flow-ci-${name}`);
  if (statSync(path).size > limit) throw new Error('Bounded CI report exceeded its limit.');
  return readFileSync(path, 'utf8');
};
let good = true;
const facts = [];
for (const [name, expectedPassed, expectedPending] of [['contracts', 2, 0], ['handler', 1, 9]]) {
  try {
    const exit = Number(read(`${name}.exit`, 16));
    const result = JSON.parse(read(`${name}.json`, 262144));
    const passed = result.numPassedTests, failed = result.numFailedTests, pending = result.numPendingTests;
    const selected = passed + failed;
    const valid = exit === 0 && result.success === true && passed === expectedPassed && failed === 0
      && pending === expectedPending && result.numTotalTests === expectedPassed + expectedPending;
    facts.push({ name, exit, selected, passed, failed, unselected: pending, valid });
    good &&= valid;
  } catch { facts.push({ name, status: 'NOT_RUN_OR_REPORT_UNKNOWN' }); good = false; }
}
let cleanup = 'unknown';
try { cleanup = read('cleanup.txt', 256).trim(); } catch { good = false; }
good &&= cleanup === 'normal-drop; connections=0; database-absent';
const summary = { source: process.env.GITHUB_SHA, facts, cleanup,
  scope: 'contracts + real PostgreSQL/Fastify.inject; not socket HTTP, runner, model or UI',
  modelExecution: 'not requested; no runtime or SDK entry selected', success: good };
const text = JSON.stringify(summary, null, 2);
console.log(text);
appendFileSync(process.env.GITHUB_STEP_SUMMARY, `\n\`\`\`json\n${text}\n\`\`\`\n`);
if (!good) process.exitCode = 1;
NODE
